async function popupContained(page, editor, info, label) {
	const popup = editor.locator('.yasqe_sharePopup');
	if (!await popup.isVisible()) await editor.locator('[title="Share your query"]').click();
	await expect(popup).toBeVisible(); await settled(page);
	const measurement = await editor.evaluate(root => {
		const rect = element => {
			const r = element.getBoundingClientRect();
			return { left: r.left, right: r.right, top: r.top, bottom: r.bottom };
		};
		const popup = root.querySelector('.yasqe_sharePopup');
		// CodeMirror's hidden editing textarea is not the revealed Share field.
		return { editor: rect(root.querySelector('.CodeMirror')), popup: rect(popup),
			text: rect(popup.querySelector('textarea, input')) };
	});
	await evidence(page, info, label, measurement);
	for (const [name, rect] of [['popup', measurement.popup], ['Share text field', measurement.text]]) {
		expect(rect.left, `${label}: ${name} left containment`).toBeGreaterThanOrEqual(measurement.editor.left - 0.5);
		expect(rect.right, `${label}: ${name} right containment`).toBeLessThanOrEqual(measurement.editor.right + 0.5);
	}
}

async function editorCaretClickable(page, editor) {
	await editor.locator('.CodeMirror').scrollIntoViewIfNeeded(); await settled(page);
	const point = await editor.locator('.CodeMirror').evaluate(root => {
		const position = root.CodeMirror.charCoords({ line: 0, ch: 3 }, 'window');
		const x = position.left, y = (position.top + position.bottom) / 2;
		return { x, y, intercepted: !!document.elementFromPoint(x, y)?.closest('.yasqe_buttons') };
	});
	expect(point.intercepted, 'Blank editor toolbar area must let caret clicks through').toBe(false);
	await page.mouse.click(point.x, point.y);
	await expect.poll(() => editor.locator('.CodeMirror').evaluate(root => root.CodeMirror.hasFocus())).toBe(true);
	const cursor = await editor.locator('.CodeMirror').evaluate(root => root.CodeMirror.getCursor());
	expect(cursor.line).toBe(0);
	expect(cursor.ch).toBeGreaterThanOrEqual(2);
	expect(cursor.ch).toBeLessThanOrEqual(4);
}

