async function compactGeometry(control) {
	return control.evaluate(element => {
		const rect = node => {
			const r = node.getBoundingClientRect();
			return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height };
		};
		const style = getComputedStyle(element), icon = element.querySelector('svg');
		const textNode = Array.from(element.childNodes).find(node => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
		const textRange = textNode ? document.createRange() : null;
		if (textRange) textRange.selectNodeContents(textNode);
		return { control: rect(element), icon: icon ? rect(icon) : null,
			text: textRange ? { value: textNode.textContent.trim(), ...rect(textRange) } : null,
			fontSize: style.fontSize, lineHeight: style.lineHeight, textAlign: style.textAlign,
			padding: ['Top', 'Right', 'Bottom', 'Left'].map(side => parseFloat(style[`padding${side}`])),
			minHeight: style.minHeight, boxSizing: style.boxSizing };
	});
}

