async function mixedControls(group) {
	return group.locator('input:not([type=hidden]), select, button').evaluateAll(elements => elements.filter(element => {
		const rect = element.getBoundingClientRect();
		return rect.width && rect.height && !element.closest('[hidden], [inert]');
	}).map(element => {
		const compact = element.matches('input[type=checkbox], input[type=radio]');
		const logical = compact ? element.closest('label')
			: element.closest('.workbench-action, .workbench-select-control') || element;
		const rect = node => {
			const r = node.getBoundingClientRect();
			return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, height: r.height,
				center: (r.top + r.bottom) / 2 };
		};
		return { id: element.id, label: logical.textContent.trim() || element.value,
			compact, logical: rect(logical), glyph: rect(element),
			logicalClass: logical.className, alignItems: getComputedStyle(logical).alignItems };
	}));
}

function alignedControlRows(measurement) {
	const controls = measurement.controls, standard = controls.filter(control => !control.compact);
	const referenceHeight = standard.length ? Math.min(...standard.map(control => control.logical.height)) : null;
	for (let index = 0; index < controls.length; index++) for (const after of controls.slice(index + 1)) {
		const before = controls[index], a = before.logical, b = after.logical;
		if (Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top) > 1
			&& (a.right <= b.left + 0.5 || b.right <= a.left + 0.5))
			closeTo(b.center - a.center, 0, `${measurement.family}: ${before.label}/${after.label} logical row centers`);
	}
	for (const control of controls.filter(control => control.compact)) {
		if (referenceHeight !== null) {
			expect(control.glyph.height, `${measurement.family}: native check/radio glyph stays compact`).toBeLessThan(referenceHeight);
			expect(control.logical.height, `${measurement.family}: labeled control owns a complete control row`)
				.toBeGreaterThanOrEqual(referenceHeight - 0.5);
		}
		closeTo(control.glyph.center - control.logical.center, 0, `${measurement.family}: ${control.label} glyph center`);
	}
}

